import { definePrimitive, dispatch, type ChangeDetails, type ChangeOptions } from "@ui-sdk/core"

import { settled } from "@/lib/action-refusal"

type ListSelectReason = "item-press" | "imperative"

type ListEntry = { value: string; label: string }

type ListOptions = {
  /** The rows as agents see them, collected from the rendered items. */
  entries?: readonly ListEntry[]
  /** Runs before a row is chosen, by a person or an agent; `details.cancel()` stops it. */
  onSelect?: (id: string, details: ChangeDetails<ListSelectReason>) => void
  /** What choosing a row does once `onSelect` allowed it, when no event will do it natively. */
  activate?: (id: string) => boolean
}

function reasonOf(options: unknown): { reason: ListSelectReason; event?: Event } {
  if (typeof options !== "object" || options === null) return { reason: "imperative" }
  const { reason = "imperative", event } = options as ChangeOptions<ListSelectReason>
  return { reason, event: event instanceof Event ? event : undefined }
}

const list = definePrimitive({
  name: "list",
  options: { entries: "value", onSelect: "callback", activate: "value" },
  state: (options: ListOptions) => ({ count: options.entries?.length ?? 0 }),
  sync: (options) => ({ count: options.entries?.length ?? 0 }),
  api: (context) => {
    const entries = () => context.options().entries ?? []
    return {
      select(id: unknown, options?: ChangeOptions<ListSelectReason>) {
        const row = entries().find((entry) => entry.value === id)
        if (!row) {
          const ids = entries().map((entry) => entry.value)
          throw new RangeError(`No row "${String(id)}". Rows: ${ids.join(", ")}.`)
        }
        const details = reasonOf(options)
        if (dispatch(context, "onSelect", row.value, details)) return settled(false, "select", details)
        const pressAlreadyActivatedRow = Boolean(details.event)
        if (pressAlreadyActivatedRow) return true
        return context.options().activate?.(row.value) ?? true
      },
      entries,
    }
  },
  slots: (slot) => ({
    root: slot({ attrs: (state) => ({ "data-count": String(state.count) }) }),
  }),
  agent: { actions: ["select"], items: (api) => api.entries() },
})

export { list }
export type { ListEntry, ListOptions, ListSelectReason }

"use client"

import type { ChangeDetails } from "@ui-sdk/core"
import { createListboxController, Listbox, type ListboxValueChangeReason } from "@ui-sdk/react/listbox"
import { usePart, usePrimitive, type PartProps, type RenderProp } from "@ui-sdk/react/primitive"
import { memo, useCallback, useMemo, useRef, useState, type FocusEvent, type ReactElement, type ReactNode } from "react"

import {
  containerClassNames,
  ListContext,
  PositionContext,
  useListContext,
  useListItemPosition,
  type ItemHandle,
  type ListContextValue,
  type ListItemPosition,
  type ListVariant,
} from "@/components/ui/list-context"
import { ListGridProvider, ListGridRoot, useListGridInstance } from "@/components/ui/list-grid"
import { list, type ListEntry, type ListOptions } from "@/components/ui/list-primitive"
import {
  RowActionsContext,
  type ListRowAction,
  type ListRowActionLabels,
  type ListRowActionsVisibility,
} from "@/components/ui/list-row-actions"
import { RowNavigationProvider, useRowNavigation } from "@/components/ui/row-navigation"
import { ListSortableRows, type ListSortableRowsProps } from "@/components/ui/list-sortable"
import { useListRowActions } from "@/components/ui/use-list-row-actions"
import { useVirtualRows, type Virtualize } from "@/components/ui/virtual-rows"
import {
  childId,
  childRowsOf,
  childText,
  defaultId,
  defaultText,
  listboxKeyDown,
  renderChild,
} from "@/components/ui/list-rows"
import { assumeType } from "@/lib/narrow"
import { cn } from "@/lib/utils"

type ListProps<Item = unknown> = Omit<PartProps<"div">, "children" | "onSelect" | "defaultValue"> & {
  /** Names the list, for screen readers and agents. */
  "aria-label": string
  variant?: ListVariant
  /** With any of `value`, `defaultValue` or `onValueChange`, the rows are options of a UI SDK Listbox. */
  value?: string | null
  defaultValue?: string | null
  onValueChange?: (id: string | null, details: ChangeDetails<ListboxValueChangeReason>) => void
  onSelect?: ListOptions["onSelect"]
  /** Rows as data, rendered by `renderItem`: every row is reachable by keyboard and agents, rendered or not. */
  items?: readonly Item[]
  getItemId?: (item: Item) => string
  renderItem?: (item: Item, index: number) => ReactNode
  /** A row's text, for agents and for find in page while it isn't rendered. */
  itemText?: (item: Item) => string
  /** `"auto"` (default) renders only the rows in view past 200 data rows. Rows only; cards never virtualize. */
  virtualize?: Virtualize
  /** A row's estimated height in px before it is measured. */
  estimateSize?: number
  /** Rows checked for a bulk action: Space or `x` on a row toggles it, and each row shows a checkbox. */
  checkedIds?: readonly string[]
  onCheckedIdsChange?: (ids: string[]) => void
  /** Rows reorder by a handle (drag, or Space and arrows). Needs data rows and no `value`; never virtualizes. */
  sortable?: boolean
  /** The new order of the row ids; pass `items` back in it. `details.cancel()` keeps the old one. */
  onReorder?: ListSortableRowsProps["onReorder"]
  /** The drag handle's name and what screen readers hear while a row moves. */
  sortableLabels?: ListSortableRowsProps["labels"]
  /**
   * The actions a row offers, by its id: buttons after its content that run without choosing the row. The list
   * becomes a grid (one tab stop; Left and Right reach a row's actions), and agents get one component per action
   * whose `run(id)` takes the row's id.
   */
  rowActions?: (id: string) => readonly ListRowAction[] | undefined
  /** `hover` (default) shows a row's actions on a fine pointer while it's hovered, focused or selected. */
  rowActionsVisibility?: ListRowActionsVisibility
  /** Names of the rows' action buttons and of the actions for agents. */
  rowActionLabels?: Partial<ListRowActionLabels>
  children?: ReactNode
}

function rootAttributes(variant: ListVariant, selectable: boolean, grid: boolean) {
  return {
    "data-slot": "list",
    "data-variant": variant,
    "data-selectable": selectable ? "" : undefined,
    "data-row-actions": grid ? "" : undefined,
  }
}

type ItemFunctions = {
  getId: (item: unknown) => string
  itemText: (item: unknown) => string
  renderItem?: (item: unknown, index: number) => ReactNode
}

type PartRenderProps = Parameters<Exclude<RenderProp, ReactElement>>[0]

type ListRowProps<Item> = {
  item: Item
  index: number
  setsize?: number
  measure?: ListItemPosition["measure"]
  renderItem: (item: Item, index: number) => ReactNode
}

// Perf: memoized row so rows in view don't re-render on scroll.
const MemoListRow = memo(function ListRow<Item>({ item, index, setsize, measure, renderItem }: ListRowProps<Item>) {
  const position = useMemo(
    () => (setsize === undefined ? null : { index, setsize, measure }),
    [index, setsize, measure],
  )
  return <PositionContext value={position}>{renderItem(item, index)}</PositionContext>
})
// Workaround: `memo` drops the row's type parameter; this gives it back.
const ListRow = assumeType<<Item>(props: ListRowProps<Item>) => ReactNode>(MemoListRow)

function List<Item = unknown>({
  "aria-label": label,
  variant = "row",
  value,
  defaultValue,
  onValueChange,
  onSelect,
  items,
  getItemId = defaultId,
  renderItem: renderItemProp,
  itemText: itemTextProp = defaultText,
  virtualize = "auto",
  estimateSize,
  checkedIds,
  onCheckedIdsChange,
  sortable = false,
  onReorder,
  sortableLabels,
  rowActions,
  rowActionsVisibility = "hover",
  rowActionLabels,
  className,
  children,
  onFocus,
  ...props
}: ListProps<Item>) {
  const selectable = value !== undefined || defaultValue !== undefined || onValueChange !== undefined
  const handles = useRef(new Map<string, ItemHandle>())
  const [registered, setRegistered] = useState<ListEntry[]>([])
  const [listbox] = useState(() => createListboxController<string>())

  const childRows = useMemo(
    () => (items === undefined && variant === "row" ? childRowsOf(children) : undefined),
    [items, variant, children],
  )
  const data: readonly unknown[] | undefined = items ?? childRows
  // Workaround: TypeScript can't relate `items` to the functions that read them, so they are typed by what `data` holds.
  const itemFunctions = assumeType<ItemFunctions>({
    getId: getItemId,
    itemText: itemTextProp,
    renderItem: renderItemProp,
  })
  const getId = childRows ? childId : itemFunctions.getId
  const itemText = childRows ? childText : itemFunctions.itemText
  const renderItem = childRows ? renderChild : itemFunctions.renderItem

  const ids = useMemo(() => data?.map(getId), [data, getId])
  const indexOf = useMemo(() => new Map(ids?.map((id, index) => [id, index])), [ids])
  const dataEntries = useMemo(
    () => data?.map((item, index) => ({ value: ids?.[index] ?? "", label: itemText(item) })),
    [data, ids, itemText],
  )

  const keyAt = useCallback((index: number) => ids?.[index] ?? String(index), [ids])
  const textAt = useCallback(
    (index: number) => (data?.[index] === undefined ? "" : itemText(data[index])),
    [data, itemText],
  )
  const sorting = sortable && !selectable && data !== undefined && renderItem !== undefined
  const { anchor, ...virtual } = useVirtualRows({
    count: data?.length ?? 0,
    findable: textAt,
    virtualize: renderItem && variant === "row" && !sorting ? virtualize : false,
    estimateSize,
    getKey: keyAt,
  })

  const fromData = data !== undefined
  const refresh = useCallback(() => {
    if (fromData) return
    setRegistered([...handles.current].map(([id, handle]) => ({ value: id, label: handle.label })))
  }, [fromData])

  const entries = dataEntries ?? registered
  const grid = rowActions !== undefined && !sorting
  const rowIds = useMemo(() => ids ?? entries.map((entry) => entry.value), [ids, entries])

  const handle = usePrimitive(list, {
    entries,
    onSelect,
    activate: (id) => {
      if (grid && selectable) return gridHandle.api.setValue(id)
      if (selectable) return listbox.setValue(id)
      const index = indexOf.get(id)
      if (!handles.current.has(id) && index !== undefined) virtual.renderNow(index)
      return handles.current.get(id)?.activate() ?? false
    },
  })

  const checkedSet = useMemo(() => new Set(checkedIds), [checkedIds])
  const checked = useMemo(
    () =>
      onCheckedIdsChange && checkedIds
        ? {
            has: (id: string) => checkedSet.has(id),
            toggle: (id: string) =>
              onCheckedIdsChange(
                checkedSet.has(id) ? checkedIds.filter((checkedId) => checkedId !== id) : [...checkedIds, id],
              ),
          }
        : undefined,
    [checkedIds, checkedSet, onCheckedIdsChange],
  )

  const gridHandle = useListGridInstance({
    ids: rowIds,
    cells: (id) => 1 + (rowActions?.(id)?.length ?? 0),
    selectable: grid && selectable,
    value,
    defaultValue,
    onValueChange,
    entries,
    onToggle: checked ? (id) => checked.toggle(id) : undefined,
    reveal: (id) => {
      const index = indexOf.get(id)
      if (index !== undefined) virtual.scrollToIndex(index)
    },
  })

  const actions = useListRowActions({ rowActions, entries, labels: rowActionLabels, visibility: rowActionsVisibility })

  const navigation = useRowNavigation({
    ids,
    onToggle: checked ? (id) => checked.toggle(id) : undefined,
    reveal: (id) => {
      const index = indexOf.get(id)
      if (index !== undefined) virtual.scrollToIndex(index)
    },
  })

  const sortableContext = useMemo(() => (sorting ? { labels: sortableLabels } : undefined), [sorting, sortableLabels])
  const context = useMemo<ListContextValue>(
    () => ({
      variant,
      selectable,
      grid,
      checked,
      sortable: sortableContext,
      register: (id, item) => {
        handles.current.set(id, item)
        refresh()
        return () => {
          if (handles.current.get(id) === item) handles.current.delete(id)
          refresh()
        }
      },
      select: (id, event) => handle.api.select(id, { reason: "item-press", event }),
    }),
    [variant, selectable, grid, checked, sortableContext, refresh, handle],
  )

  let rows: ReactNode = children
  if (sorting && data && renderItem && ids) {
    rows = (
      <ListSortableRows
        label={label}
        grid={variant === "card"}
        ids={ids}
        indexOf={indexOf}
        textAt={textAt}
        checkedIds={checkedIds}
        onCheckedIdsChange={onCheckedIdsChange}
        onReorder={onReorder}
        labels={sortableLabels}
        renderRow={(index) => {
          const item = data[index]
          return item === undefined ? null : (
            <ListRow key={ids[index]} item={item} index={index} renderItem={renderItem} />
          )
        }}
      />
    )
  } else if (data && renderItem) {
    const GapTag = selectable || grid ? "div" : "li"
    rows = virtual.segments.map((segment) => {
      if (segment.type === "gap") {
        return <GapTag key={segment.key} aria-hidden="true" data-slot="list-gap" style={{ height: segment.size }} />
      }
      const item = data[segment.index]
      if (item === undefined) return null
      return (
        <ListRow
          key={segment.key}
          item={item}
          index={segment.index}
          setsize={virtual.enabled ? data.length : undefined}
          measure={virtual.measureElement}
          renderItem={renderItem}
        />
      )
    })
  }

  const rootProps = {
    ...props,
    ...rootAttributes(variant, selectable, grid),
    ref: anchor,
    "aria-label": label,
    onFocus: (event: FocusEvent<HTMLDivElement>) => {
      onFocus?.(event)
      if (!virtual.enabled || !(event.target instanceof Element)) return
      const index = Number(event.target.closest<HTMLElement>("[data-index]")?.dataset.index ?? Number.NaN)
      if (!Number.isNaN(index)) virtual.pin(index)
    },
    className: cn("min-w-0", containerClassNames[variant], virtual.enabled && "relative", className),
  }

  const listChildren = (
    <ListContext value={context}>
      <RowActionsContext value={actions.context}>{rows}</RowActionsContext>
    </ListContext>
  )

  const partProps = grid
    ? {
        ...rootProps,
        "aria-rowcount": virtual.enabled ? data?.length : undefined,
        className: cn(rootProps.className, "outline-none"),
        children: <ListGridProvider handle={gridHandle}>{listChildren}</ListGridProvider>,
        render: (part: Record<string, unknown>) => <ListGridRoot {...part} handle={gridHandle} />,
      }
    : selectable
      ? {
          ...rootProps,
          className: cn(rootProps.className, "outline-none"),
          children: listChildren,
          render: ({ ref, ...part }: PartRenderProps) => (
            <Listbox<string>
              {...part}
              ref={ref}
              render={(listboxProps) => <div {...listboxProps} data-slot="list" />}
              controller={listbox}
              value={value}
              defaultValue={defaultValue}
              onValueChange={onValueChange}
              onHighlight={(_value, details) => {
                if (virtual.enabled && details.index >= 0) virtual.scrollToIndex(details.index)
              }}
              onKeyDownCapture={(event) => listboxKeyDown(event, (id) => listbox.setValue(id))}
            />
          ),
        }
      : {
          ...rootProps,
          // Workaround: Safari drops list semantics under Preflight's list-style: none unless the role is explicit.
          role: sorting ? "group" : "list",
          className: sorting ? cn("min-w-0", className) : rootProps.className,
          children: (
            <ListContext value={context}>
              <RowActionsContext value={actions.context}>
                <RowNavigationProvider handle={navigation}>{rows}</RowNavigationProvider>
              </RowActionsContext>
            </ListContext>
          ),
        }

  const tag: "div" | "ul" = selectable || sorting || grid ? "div" : "ul"
  const root = usePart(handle, "root", {}, partProps, tag)
  if (!actions.roots) return root
  // Spec: a grid or list owns only rows, so the action roots render outside it.
  return (
    <>
      {root}
      {actions.roots}
    </>
  )
}

export { containerClassNames, List, useListContext, useListItemPosition }
export type { ItemHandle, ListItemPosition, ListProps, ListVariant }

"use client"

import { Button } from "@ui-sdk/react/button"
import { ListboxItem } from "@ui-sdk/react/listbox"
import { renderElement, type PartProps } from "@ui-sdk/react/primitive"
import { createElement, useState, type ComponentProps, type ReactElement, type ReactNode } from "react"

import { Checkbox, CheckboxIndicator } from "@/components/ui/checkbox"
import { useListContext, useListItemPosition, type ListVariant, List, type ListProps } from "@/components/ui/list"
import { ListGroup, type ListGroupProps } from "@/components/ui/list-group"
import { ListGridCell, ListGridRow, useListGrid } from "@/components/ui/list-grid"
import { ListRowActionCells, useRowActions } from "@/components/ui/list-row-actions"
import { NavigableRow } from "@/components/ui/row-navigation"
import { SortableHandle, SortableItem } from "@/components/ui/sortable"
import { Tooltip, TooltipContent, TooltipTrigger } from "@/components/ui/tooltip"
import { useListItemRegistration, useTruncated } from "@/components/ui/use-list-item"
import type { Tone } from "@/lib/tone"
import { cn } from "@/lib/utils"

// Perf: contain-content, so moving focus repaints only one row.
const rowClassNames = {
  row: "rounded-control contain-content hover:bg-accent/60 data-checked:bg-accent/60 data-selected:bg-accent data-selected:text-accent-foreground",
  card: "rounded-lg border bg-card/(--glass-opacity) text-card-foreground shadow-surface backdrop-surface hover:border-ring data-selected:border-ring data-selected:bg-accent data-selected:text-accent-foreground data-selected:ring-3 data-selected:ring-ring/25",
} satisfies Record<ListVariant, string>

const stretchedClassNames = {
  row: "after:rounded-control focus-visible:after:ring-inset",
  card: "after:rounded-lg",
} satisfies Record<ListVariant, string>

type ListItemEmphasis = "muted" | "strong"

const toneClassNames = {
  neutral: "bg-neutral-soft text-neutral-soft-foreground",
  info: "bg-info-soft text-info-soft-foreground",
  success: "bg-success-soft text-success-soft-foreground",
  warning: "bg-warning-soft text-warning-soft-foreground",
  destructive: "bg-destructive-soft text-destructive-soft-foreground",
  violet: "bg-violet-soft text-violet-soft-foreground",
} satisfies Record<Tone, string>

/** An icon on a tinted square, for a row's `leading`. */
function IconTile({ tone = "neutral", className, render, ...props }: PartProps<"span"> & { tone?: Tone }) {
  return renderElement(
    "span",
    {
      "aria-hidden": true,
      "data-slot": "icon-tile",
      className: cn(
        "flex size-8 shrink-0 items-center justify-center rounded-control [&_svg]:size-4",
        toneClassNames[tone],
        className,
      ),
      ...props,
    },
    render,
  )
}

function ListItemTitle({ className, render, ...props }: PartProps<"span">) {
  return renderElement(
    "span",
    {
      "data-slot": "list-item-title",
      className: cn("line-clamp-2 min-w-0 text-body font-medium break-words", className),
      ...props,
    },
    render,
  )
}

function ListItemMeta({ className, render, ...props }: PartProps<"div">) {
  return renderElement(
    "div",
    {
      "data-slot": "list-item-meta",
      className: cn("flex flex-wrap items-center gap-inline text-caption text-muted-foreground", className),
      ...props,
    },
    render,
  )
}

function ListItemActions({ className, render, ...props }: PartProps<"div">) {
  return renderElement(
    "div",
    {
      "data-slot": "list-item-actions",
      className: cn("relative z-10 flex shrink-0 items-center gap-inline self-center", className),
      ...props,
    },
    render,
  )
}

function followWithoutSelectingAgain(primary: HTMLElement) {
  primary.setAttribute("data-selecting", "")
  primary.click()
}

type ListItemProps = {
  id: string
  title: string
  leading?: ReactNode
  subtitle?: ReactNode
  /** A StatusPill; on a narrow row it wraps below the title instead of squeezing it. */
  status?: ReactNode
  /** Inline chips. */
  meta?: ReactNode
  /** An avatar or a time, at the end. */
  trailing?: ReactNode
  /**
   * Buttons or a menu, in a List without `rowActions`. Rows of a selectable List are options, which can't hold
   * controls, so it ignores them there: give the List `rowActions` instead, which reach the keyboard as grid cells.
   */
  actions?: ReactNode
  selected?: boolean
  href?: string
  onSelect?: () => void
  /** Overrides the List's variant. */
  variant?: ListVariant
  /** `muted` fades the row's text, like a read message; `strong` sets it in a medium weight, like an unread one. */
  emphasis?: ListItemEmphasis
  /** The checkbox's name in a list with `checkedIds`; English by default. */
  checkLabel?: string
  className?: string
}

function ListItem({
  id,
  title,
  leading,
  subtitle,
  status,
  meta,
  trailing,
  actions,
  selected = false,
  href,
  onSelect,
  variant: variantProp,
  emphasis,
  checkLabel,
  className,
}: ListItemProps) {
  const context = useListContext()
  const position = useListItemPosition()
  const variant = variantProp ?? context?.variant ?? "row"
  const grid = useListGrid()
  const rowActions = useRowActions()
  const option = (context?.selectable ?? false) && !grid
  const gridSelects = grid !== null && (context?.selectable ?? false)
  const [titleNode, setTitleNode] = useState<HTMLElement | null>(null)
  const truncated = useTruncated(titleNode)
  const [primary, setPrimary] = useState<HTMLElement | null>(null)

  useListItemRegistration(context?.register, id, title, option, () => {
    if (href) {
      if (!primary) return false
      followWithoutSelectingAgain(primary)
      return true
    }
    if (!onSelect) return false
    onSelect()
    return true
  })

  const titleText = (
    <ListItemTitle ref={setTitleNode} title={option && truncated ? title : undefined}>
      {title}
    </ListItemTitle>
  )
  const pressable = !option && (grid !== null || href !== undefined || onSelect !== undefined)
  const primaryProps = {
    ref: setPrimary,
    "data-slot": "list-item-primary",
    "aria-current": selected && !gridSelects ? (href ? ("page" as const) : ("true" as const)) : undefined,
    className: cn(
      "min-w-0 cursor-pointer text-start outline-none after:absolute after:inset-0 focus-visible:after:ring-2 focus-visible:after:ring-ring",
      stretchedClassNames[variant],
    ),
    onClick: (event: React.MouseEvent<HTMLElement>) => {
      const target = event.currentTarget
      if (target.dataset.selecting !== undefined) {
        delete target.dataset.selecting
        return
      }
      if (context && !context.select(id, event.nativeEvent)) {
        event.preventDefault()
        return
      }
      if (gridSelects && grid) grid.api.setValue(id, { reason: "item-press", event: event.nativeEvent })
      if (!href) onSelect?.()
    },
    children: titleText,
  }
  const element: ReactElement<Record<string, unknown>> = href
    ? createElement("a", { href, ...primaryProps })
    : createElement(Button, {
        ...primaryProps,
        render: (props: ComponentProps<"button">) => <button {...props} data-slot="list-item-primary" />,
      } as Record<string, unknown>)
  let heading: ReactNode = titleText
  if (pressable) {
    // Perf: tooltip content mounts only while the title is cut off.
    heading = (
      <Tooltip type="label" disabled={!truncated}>
        {grid ? (
          <ListGridCell handle={grid} id={id} col={0} render={<TooltipTrigger render={element} />} />
        ) : (
          <NavigableRow id={id} render={<TooltipTrigger render={element} />} />
        )}
        {truncated && <TooltipContent>{title}</TooltipContent>}
      </Tooltip>
    )
  }
  const checked = option ? undefined : context?.checked
  const checkbox = checked && (
    <span className="relative z-10 flex min-h-lh shrink-0 items-center">
      <Checkbox
        render={(props) => <button {...props} tabIndex={-1} />}
        aria-label={checkLabel ?? `Select ${title}`}
        checked={checked.has(id)}
        onCheckedChange={() => checked.toggle(id)}
      >
        <CheckboxIndicator />
      </Checkbox>
    </span>
  )

  const sortable = option ? undefined : context?.sortable
  const handle = sortable && (
    <span className="relative z-10 -my-px flex min-h-lh shrink-0 items-center">
      <SortableHandle label={title} labels={sortable.labels} />
    </span>
  )

  const main = (
    <>
      <div className="flex min-w-0 grow basis-60 items-start gap-items">
        {handle}
        {checkbox}
        {leading && (
          <span
            data-slot="list-item-leading"
            className="flex min-h-lh shrink-0 items-center text-muted-foreground [&_svg]:size-4"
          >
            {leading}
          </span>
        )}
        <div className="flex min-w-0 flex-1 flex-col gap-inline">
          <div className="flex flex-wrap items-start gap-x-items gap-y-inline">
